// Chevrons — Figma nodes 40002082:49961 (down), 40002128:29217 (up),
// 40002182:52555 (left), 40002182:52552 (right). All four export the identical path
// (M0.312 0.390 L7.812 6.390 L15.312 0.390, 15x6, stroke #191919): the design system
// draws one glyph and rotates it, and the export strips the rotation. Reproduced here
// as the same polyline at each of the four rotations about the centre of a 24x24 box,
// which matches the node footprints Figma reports — 15x6 for down/up, 6x15 for left/right.
// viewBox is 24 rather than this file's usual 20 because that is the frame the design
// system draws them in (confirmed via Icon_chevron_down, a 24x24 symbol).
// No strokeWidth, linecap or linejoin: Figma specifies none, so the SVG defaults
// (1 / butt / miter) are the faithful reproduction.
export const ChevronDownIcon = createIcon({
  displayName: 'ChevronDownIcon',
  viewBox: '0 0 24 24',
  path: <path d="M4.5 9L12 15L19.5 9" stroke="currentColor" fill="none" />,
});

