  displayName: 'PlusIcon',
  viewBox: '0 0 12 12',
  // strokeWidth 0.6, not the SVG default of 1: this icon's real Figma export (node
  // I9323:96527;40002540:26077;40002540:26158, "Icon_plus") is viewBox 12x12 with no
  // explicit stroke-width, which at the default renders 1/12 (8.3%) of the icon box —
  // ~67% thicker than MinusIcon's shipped 20x20 viewBox at its own default (1/20, 5%).
  // Both render through the same ZimmIcon boxSize with no per-icon override, so left at
  // its own default this glyph would visibly out-weigh Minus in the stepper. 0.6 = 12 *
  // (1/20) matches Minus's current ratio exactly. Note MinusIcon's own real Figma export
  // for the same stepper location is ALSO viewBox 12x12, not 20x20 — a pre-existing
  // discrepancy on an icon outside this step's scope, not corrected here.
  path: <path d="M6 2V10M10 6H2" stroke="currentColor" strokeWidth="0.6" strokeLinejoin="round" fill="none" />,
});

