2	import { describe, test, expect, vi } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
5	import { FooterNavColumn, hasIntentionalLineBreak } from './index';
6	import type { NavGroupEntry, LinkEntry } from 'app/types/contentful';
7	
8	// FooterNavColumn renders its links through ZimmNavItem, which now calls useMultiSite()
9	// (regional link prefixing fix) — its real implementation transitively pulls in
10	// @salesforce/retail-react-app/app/contexts, a `.js` file with raw JSX Vite's import-analysis
11	// can't parse under Vitest. Same mock footer/index.test.tsx (this component's own container
12	// test) and header/rightBar/index.test.tsx already use for this hook.
13	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
14	  default: vi.fn(),
15	}));
16	
17	vi.mocked(useMultiSite).mockReturnValue({
18	  site: { id: 'ZimmermannAU', alias: 'au' },
19	  locale: { id: 'en-AU', alias: 'en-AU' },
20	  buildUrl: (path: string) => path,
21	});
22	
23	// ZimmIcon pulls in the base SFCC icons barrel (app/components/icons), which has a top-level
24	// side effect (AmexSymbol.viewBox = ...) that throws under Vitest — SVG imports resolve to raw
25	// path strings here, not components. No test in this repo has rendered an icon-consuming
26	// component before, so this gap was never caught; fixing the SVG transform lives in
27	// vitest.config.ts, Tier 1 test config this task cannot touch. Mocking the smallest surface
28	// (ZimmIcon itself) routes around it without losing anything this test actually asserts on —
29	// the aria-label/href under test come from ZimmContactIconRow's own wrapper, not from ZimmIcon.
30	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
31	  // Forwards aria-label/aria-hidden — ZimmContactIconRow's fallback (no-href) branch puts the
