26	import React from 'react';
27	import { describe, test, expect, vi, beforeEach } from 'vitest';
28	import { render, screen, fireEvent } from '@testing-library/react';
29	import { ChakraProvider } from '@chakra-ui/react';
30	import { IntlProvider } from 'react-intl';
31	import { MemoryRouter } from 'react-router-dom';
32	import theme from 'app/theme';
33	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
34	import { useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
35	import ProductItem from '.';
36	
37	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
38	  default: vi.fn(),
39	}));
40	
41	// SFCC-795: wraps the REAL useMultiStyleConfig (a bare re-export of @chakra-ui/react's own hook —
42	// confirmed in node_modules/@salesforce/retail-react-app/.../shared/ui/useMultiStyleConfig) in a
43	// vi.fn so its call args are inspectable, without changing what it actually returns/does. Lets
44	// the `hasError` wiring test below prove the exact props ProductItem passes through, rather than
45	// asserting a media-query-scoped computed style value jsdom does not reliably resolve (see this
46	// file's own docblock).
47	vi.mock('@salesforce/retail-react-app/app/components/shared/ui', async (importOriginal) => {
48	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/components/shared/ui')>();
49	  return {
50	    ...actual,
51	    useMultiStyleConfig: vi.fn(actual.useMultiStyleConfig),
52	  };
53	});
54	
55	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
56	  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
57	  useDerivedProduct: () => ({
58	    stepQuantity: 1,
59	    showInventoryMessage: false,
60	    inventoryMessage: '',
61	    quantity: 1,
62	    setQuantity: vi.fn(),
63	  }),
64	}));
