66	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
67	  useCurrentBasket: () => ({ data: undefined }),
68	}));
69	
70	// item-attributes.tsx imports PromoPopover unconditionally, which imports the base SFCC icons
71	// barrel — that barrel has a top-level side effect (`AmexSymbol.viewBox = ...`) that throws
72	// under Vitest (SVG imports resolve to raw path strings here, not components). Same root cause,
73	// same fix shape, as testing.md's documented ZimmIcon workaround, just via a different import
74	// path (PromoPopover, not ZimmIcon) — not fixable from this test file beyond mocking it away.
75	vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
76	  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
77	}));
78	
79	vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
80	  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
81	  return {
82	    ...actual,
83	    usePromotions: () => ({ data: undefined }),
84	    useProducts: () => ({ data: undefined, isLoading: false }),
85	    useProduct: () => ({ data: undefined, isLoading: false }),
86	  };
87	});
