89	// Bypasses the real utility's own variationAttributes/variationValues matching logic — this
90	// test is about ProductItem's own render contract (does a combined value render as one node),
91	// not about re-proving getDisplayVariationValues' own correctness. See
92	// item-variant/item-attributes.tsx's own SFCC-270 docblock for combineAttributeValues' contract.
93	vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
94	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
95	  return {
96	    ...actual,
97	    getDisplayVariationValues: () => ({ Colour: 'Lilac Sand', Size: 'One size' }),
98	  };
99	});
100	
101	const mockUseMultiSite = vi.mocked(useMultiSite);
102	const mockUseMultiStyleConfig = vi.mocked(useMultiStyleConfig);
103	
104	// ChakraProvider with this project's own theme is required, not optional here — without it,
105	// `textStyle="productNames"`/`"price"`/`"caption"` resolve against Chakra's default (empty)
106	// textStyles, and item-price.tsx's `useBreakpointValue` throws outright reading
107	// `theme.breakpoints` off an undefined theme. Same setup zimmButton's own test uses.
108	const renderWithProviders = (ui: React.ReactElement) =>
109	  render(
110	    <ChakraProvider theme={theme}>
111	      <MemoryRouter>
112	        <IntlProvider locale="en-AU" defaultLocale="en-AU">
113	          {ui}
114	        </IntlProvider>
115	      </MemoryRouter>
116	    </ChakraProvider>,
117	  );
118	
119	const MOCK_LINE_ITEM = {
120	  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
121	  productId: '25595021M',
122	  id: '25595021M',
123	  productName: 'Lilac Sand Silk Midi Dress',
124	  name: 'Lilac Sand Silk Midi Dress',
125	  price: 495,
126	  priceAfterItemDiscount: 495,
127	  pricePerUnit: 495,
128	  quantity: 1,
129	  imageGroups: [
130	    {
131	      viewType: 'small',
132	      images: [{ alt: 'Lilac Sand Silk Midi Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
133	    },
134	  ],
135	};
136	
137	describe('ProductItem', () => {
138	  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
139	  // useBreakpointValue internally, which calls it — a per-file polyfill, not a change to the
140	  // frozen vitest.setup.ts (Tier 1). Same pattern and reasoning as drawer-menu/index.test.tsx's
141	  // own beforeEach.
142	  beforeEach(() => {
143	    Object.defineProperty(window, 'matchMedia', {
144	      writable: true,
145	      value: vi.fn().mockImplementation((query: string) => ({
146	        matches: false,
147	        media: query,
148	        onchange: null,
149	        addListener: vi.fn(),
150	        removeListener: vi.fn(),
151	        addEventListener: vi.fn(),
152	        removeEventListener: vi.fn(),
153	        dispatchEvent: vi.fn(),
154	      })),
155	    });
156	
157	    mockUseMultiSite.mockReturnValue({
158	      site: { id: 'ZimmermannAU' },
159	      buildUrl: (path: string) => path,
160	    });
161	
162	    // SFCC-795: fresh call history per test — mockUseMultiStyleConfig still delegates to the
163	    // real implementation (see the top-of-file vi.mock), this only clears recorded .mock.calls.
164	    mockUseMultiStyleConfig.mockClear();
165	  });
166	
167	  test('renders the image with an alt, the name uppercase, the price, and one combined colour+size node', () => {
168	    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
169	
170	    // Image renders with an alt.
171	    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
172	
173	    // Name renders uppercase (textStyle="productNames" sets text-transform, not literal casing —
174	    // the DOM text content itself stays as authored). Asserted on the <Heading> textStyle is
175	    // actually applied to, not the nested <Link> — see item-variant/index.test.tsx's own note
176	    // on why (text-transform is CSS-inherited, and jsdom's getComputedStyle does not reliably
177	    // resolve inherited declarations).
178	    expect(screen.getByRole('heading', { level: 2 })).toHaveStyle({ textTransform: 'uppercase' });
179	
180	    // Price renders — DisplayPrice/CurrentPrice formats $495.00 via react-intl; rendered twice
181	    // (mobile + desktop slots both exist in the DOM under jsdom, which does not evaluate CSS
182	    // media queries — see header/rightBar/index.test.tsx's own note on this exact behaviour).
183	    expect(screen.getAllByText('$495.00').length).toBeGreaterThan(0);
184	
185	    // The colour+size string renders as ONE text node containing both values — not two
186	    // separate nodes. An exact-string query only matches if both values live in the same node.
187	    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
188	  });
189	
190	  // Round 2 rework, must-fix 4: the gift-card capability slot. Only the capability is asserted
191	  // here — not real gift-card detection, which this build still cannot do (see this component's
192	  // own docblock).
193	  test('hideStepperAndActions suppresses the stepper and every actions surface, and nothing throws', () => {
194	    expect(() =>
195	      renderWithProviders(
196	        <ProductItem
197	          product={MOCK_LINE_ITEM}
198	          primaryAction={<button type="button">Remove</button>}
199	          secondaryActions={<button type="button">Edit</button>}
200	          deliveryActions={<span>Ship to store</span>}
201	          hideStepperAndActions
202	        />,
203	      ),
204	    ).not.toThrow();
205	
206	    // Stepper: ProductQuantityPicker's own "Quantity:" label is the only source of this text in
207	    // this render tree (product-item/index.tsx never passes includeQuantity to
208	    // CartItemVariantAttributes), so its absence proves the stepper itself did not render.
209	    expect(screen.queryByText('Quantity:')).not.toBeInTheDocument();
210	
211	    // Actions: primaryAction/secondaryActions/deliveryActions all suppressed.
212	    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
213	    expect(screen.queryByRole('button', { name: 'Edit' })).not.toBeInTheDocument();
214	    expect(screen.queryByText('Ship to store')).not.toBeInTheDocument();
215	
216	    // The rest of the component is unaffected — image/name/price/attributes still render.
217	    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
218	    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
219	  });
220	
221	  test('every existing caller (hideStepperAndActions omitted) is unaffected — the stepper and actions still render', () => {
222	    renderWithProviders(
223	      <ProductItem
224	        product={MOCK_LINE_ITEM}
225	        primaryAction={<button type="button">Remove</button>}
226	        secondaryActions={<button type="button">Edit</button>}
227	        deliveryActions={<span>Ship to store</span>}
228	      />,
229	    );
230	
231	    expect(screen.getByText('Quantity:')).toBeInTheDocument();
232	    expect(screen.getAllByRole('button', { name: 'Remove' }).length).toBeGreaterThan(0);
233	    expect(screen.getByRole('button', { name: 'Edit' })).toBeInTheDocument();
234	    expect(screen.getAllByText('Ship to store').length).toBeGreaterThan(0);
235	  });
236	
237	  // CodeRabbit (SFCC-11 cumulative review): product-quantity-picker.tsx's handleQuantityChange
238	  // unconditionally calls `.then(...)` on onItemQuantityChange's return value. The old default,
239	  // `noop`, returned undefined synchronously - `undefined.then` throws before this test's key
240	  // handler even finishes. This proves a caller that omits the prop entirely can still actually
241	  // change the quantity without throwing, not just that rendering alone doesn't throw.
242	  //
243	  // Uses an ArrowUp keydown on the quantity input, not a click/mousedown on the increment button:
244	  // confirmed empirically (not assumed) that fireEvent.click and fireEvent.mouseDown on the
245	  // button never reach handleQuantityChange at all in this environment - a version of this test
246	  // written against the pre-fix `noop` default still passed with either, because the interaction
247	  // itself never fired, not because the fix was safe. ArrowUp on the input reliably invokes the
248	  // real onChange -> handleQuantityChange chain.
249	  //
250	  // Mutation-tested against the actual pre-fix default: the resulting TypeError is thrown
251	  // asynchronously inside Chakra's own number-input internals (a React event-handler microtask),
252	  // not synchronously inside this test's own call stack - so `not.toThrow()` itself does not
253	  // catch it, and the specific `test()` block still reports as passed. What DOES catch it: Vitest
254	  // reports the async throw as an unhandled error for the run and the process exits non-zero
255	  // (confirmed directly: exit code 1 with the bug present, exit code 0 with the fix in place) -
256	  // which is exactly what CI gates on. Noted here so a future reader isn't confused about why an
257	  // apparently-clean assertion is the real regression guard; the throw itself is the proof.
258	  test('omitting onItemQuantityChange and actually changing quantity does not throw', () => {
259	    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
260	
261	    expect(() => {
262	      fireEvent.keyDown(screen.getByLabelText('Quantity'), { key: 'ArrowUp' });
263	    }).not.toThrow();
264	  });
265	
266	  // SFCC-795 pass criterion 7: `message` omitted (every existing caller today) renders nothing,
267	  // and ZimmCartItem resolves `hasError` to false. product-item.css.test.ts proves separately,
268	  // at the recipe level, that hasError:false keeps the Item Details gap at its existing 12px
269	  // desktop token — this test proves the WIRING that gets it there (see this file's own
270	  // docblock for why not a computed-style assertion on the media-query-scoped gap value itself).
271	  test('message omitted: nothing renders, and ZimmCartItem resolves hasError=false', () => {
272	    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
273	
274	    expect(screen.queryByTestId('zimm-inline-message')).not.toBeInTheDocument();
275	
276	    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
277	    expect(cartItemCalls).toHaveLength(1);
278	    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
279	  });
280	
281	  test('message with variant="warning": renders the message, but ZimmCartItem still resolves hasError=false', () => {
282	    renderWithProviders(
283	      <ProductItem
284	        product={MOCK_LINE_ITEM}
285	        message={{ variant: 'warning', text: 'Maximum purchase quantity reached for this size' }}
286	      />,
287	    );
288	
289	    expect(screen.getByText('Maximum purchase quantity reached for this size')).toBeInTheDocument();
290	
291	    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
292	    expect(cartItemCalls).toHaveLength(1);
293	    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
294	  });
295	
296	  test('message with variant="error": renders the message, and ZimmCartItem resolves hasError=true', () => {
297	    renderWithProviders(
298	      <ProductItem product={MOCK_LINE_ITEM} message={{ variant: 'error', text: 'This item is unavailable' }} />,
299	    );
300	
301	    expect(screen.getByText('This item is unavailable')).toBeInTheDocument();
302	
303	    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
304	    expect(cartItemCalls).toHaveLength(1);
305	    expect(cartItemCalls[0][1]).toEqual({ hasError: true });
306	  });
307	
308	  // SFCC-795 pass criterion 4: real DOM-order assertion via compareDocumentPosition, not just
309	  // "both nodes are present somewhere."
310	  test('message renders in DOM order between the stepper and the actions (secondaryActions)', () => {
311	    renderWithProviders(
312	      <ProductItem
313	        product={MOCK_LINE_ITEM}
314	        secondaryActions={<button type="button">Edit</button>}
315	        message={{ variant: 'error', text: 'This item is unavailable' }}
316	      />,
317	    );
318	
319	    const stepperNode = screen.getByText('Quantity:');
320	    const messageNode = screen.getByTestId('zimm-inline-message');
321	    const actionsNode = screen.getByRole('button', { name: 'Edit' });
322	
323	    // messageNode follows stepperNode in document order.
324	    expect(stepperNode.compareDocumentPosition(messageNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
325	    // actionsNode follows messageNode in document order — i.e. the message precedes the actions row.
326	    expect(messageNode.compareDocumentPosition(actionsNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
327	  });
328	});
