            </Box>
            <Text textStyle="caption" textAlign="center">
              {type}
            </Text>
          </VStack>
        ))}
      </SimpleGrid>
    </Box>
  ),
};

export const AllSizes: Story = {
  render: () => (
    <Box p={8} display="flex" gap={8} alignItems="flex-end">
      {(['sm', 'md', 'lg'] as const).map((size) => (
        <VStack key={size} gap={2} align="center">
          <ZimmIcon type="search" size={size} aria-hidden={true} />
          <Text textStyle="caption">{iconSizes[size]}</Text>
        </VStack>
      ))}
    </Box>
  ),
};

export const Decorative: Story = {
  args: {
    type: 'close',
    size: 'md',
    'aria-hidden': true,
  },
};

